@startuml

class SensorController {
}

class Apartment {
  + address : string
  + email : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

class EMonitor {}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" -- "*" Apartment : manages
SensorController "1" -- "*" Inhabitant : manages
Apartment "1" *-- "2..*" Room : consists of
Room "1" *-- "*" Sensor : contains
Sensor "1" -- "*" MeasuredValue : records
Sensor "0..1" -- "0..1" MeasuredValue : lastValue
Sensor "*" -- "1" Room : is assigned to
Inhabitant "*" -- "*" Sensor : configures
Inhabitant "*" -- "*" Sensor : queries
EMonitor "1" -- "*" Sensor : checks thresholds
EMonitor "1" -- "1" SensorController : uses

@enduml

